/**
 * Personal API tokens. Only the hash of a token's secret is ever passed in or
 * stored, and no read here returns it — `ApiToken` has no field for it.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/**
 * Inserts the token unless the user already holds `limit` usable ones in the
 * org, and answers `null` in that case. Counting and inserting share one
 * synchronous transaction, so two concurrent creates cannot both slip under
 * the limit. "Usable" is judged at `token.createdAt`.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, token.orgId),
          eq(apiTokens.userId, token.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, token.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: token.orgId,
        userId: token.userId,
        name: token.name,
        scope: token.scope,
        prefix: token.prefix,
        tokenHash: token.tokenHash,
        expiresAt: token.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: token.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

/** Newest first; `rowid` breaks ties between tokens created in the same instant. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), sql`${apiTokens}.rowid desc`)
    .all();

  return rows.map(toApiToken);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * The one read that is not tenant-scoped: authentication starts from a secret
 * and only learns the organization from the row it finds.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Revokes one token. Answers `null` when nothing changed — the token does not
 * exist in the org, or was already revoked and keeps its original `revokedAt`.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
