cat > src/server/services/api-token-service.ts <<'EOF'
/**
 * Personal API tokens: minting, listing, revoking and authenticating them, plus the rule that a removed member's tokens die with their membership.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { resolveActor } from "./member-service";
import {
  actorEnvelope,
  apiTokenResource,
  envelope,
  requireFound,
} from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** How many usable (unrevoked, unexpired) tokens one user may hold per org. */
const MAX_USABLE_TOKENS = 5;

/** Every secret starts with this, so a leaked one is easy to spot and report. */
const TOKEN_SECRET_PREFIX = "tfk_";

/** How much of the secret is kept, in the clear, as `ApiToken.prefix`. */
const PREFIX_LENGTH = 12;

/** Length in bytes of the random part of a secret. */
const TOKEN_BYTES = 32;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Raised when a user already holds the maximum number of usable tokens. */
export class ApiTokenLimitError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly limit: number) {
    super(`You can have at most ${limit} active API tokens in an organization`);
    this.name = "ApiTokenLimitError";
  }
}

/**
 * Mints a token for the actor. The secret is returned here and nowhere else:
 * only its hash is stored, and neither reaches the event bus or the audit log.
 * A `read` token is open to every role; a `write` token needs `member`.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  assertCan(
    actor,
    parsed.scope === "write" ? "api_token:create_write" : "api_token:create",
    apiTokenResource(parsed.orgId, actor.userId),
  );

  const now = new Date();
  const token = `${TOKEN_SECRET_PREFIX}${randomToken(TOKEN_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) throw new ApiTokenLimitError(MAX_USABLE_TOKENS);

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/** Someone's tokens, revoked and expired included, newest first. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, userId));
  return apiTokenRepo.listApiTokens(orgId, userId);
}

/**
 * Revoking is idempotent: a token that is already revoked comes back as it
 * was, with its original `revokedAt`, and nothing further is audited.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const token = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, token.userId));

  if (token.revokedAt !== null) return token;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
