import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** How many usable (unrevoked, unexpired) tokens one user may hold per org. */
const MAX_USABLE_TOKENS = 5;

/** Every secret starts with this, so a leaked one is easy to spot and report. */
const TOKEN_SECRET_PREFIX = "tfk_";

/** How much of the secret is kept, in the clear, as `ApiToken.prefix`. */
const PREFIX_LENGTH = 12;

/** Length in bytes of the random part of a secret. */
const TOKEN_BYTES = 32;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Raised when a user already holds the maximum number of usable tokens. */
export class ApiTokenLimitError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly limit: number) {
    super(`You can have at most ${limit} active API tokens in an organization`);
    this.name = "ApiTokenLimitError";
  }
}

/**
 * Mints a token for the actor. The secret is returned here and nowhere else:
 * only its hash is stored, and neither reaches the event bus or the audit log.
 * A `read` token is open to every role; a `write` token needs `member`.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  assertCan(
    actor,
    parsed.scope === "write" ? "api_token:create_write" : "api_token:create",
    apiTokenResource(parsed.orgId, actor.userId),
  );

  const now = new Date();
  const token = `${TOKEN_SECRET_PREFIX}${randomToken(TOKEN_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) throw new ApiTokenLimitError(MAX_USABLE_TOKENS);

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

