    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, token.userId));

  if (token.revokedAt !== null) return token;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
    // Lost a race with another revoke: report its result, audit nothing twice.
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    ownerId: revoked.userId,
    name: revoked.name,
    scope: revoked.scope,
    reason: "revoked",
  });

  return revoked;
}

