  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchLastUsed(
    apiToken.orgId,
    apiToken.id,
    toIsoTimestamp(now),
  );

  return {
    userId: member.userId,
    orgId: member.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Attaches the handlers that keep tokens in step with membership. Called once
 * from `event-registry`; the returned function detaches them all.
 */
export function registerApiTokenListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    // A removed member's tokens must not outlive their membership. Handlers
    // are awaited by `emit`, so this has finished when `removeMember` resolves.
    subscribe("member.removed", async (payload) => {
